'use strict';
function collectionCounts(){return {first:MCQS.length-SECOND_HALF_MCQS.length,second:SECOND_HALF_MCQS.length,mcqs:MCQS.length,guided:EXERCISES.length,debug:DEBUG_CASES.length,reading:READING_EXAMPLES.length,course:PROGRAMS.filter(p=>!p.reading).length,allPrograms:PROGRAMS.length,total:MCQS.length+EXERCISES.length+PROGRAMS.length+DEBUG_CASES.length};}
function practiceTabs(current){return `<div class="practice-tabs" role="navigation" aria-label="Practice sets"><a href="#banks" ${current==='banks'?'aria-current="page"':''}>All practice sets</a><a href="#banks/weeks-1-6" ${current==='first'?'aria-current="page"':''}>Weeks 1–6</a><a href="#banks/weeks-7-14" ${current==='second'?'aria-current="page"':''}>Weeks 7–14</a></div>`;}
function dashboard(){const c=collectionCounts(),s=stats();const paths=[['materials','Weekly course materials',14,'weeks','Lecture slides and detailed reading notes from Moodle: 28 PDFs and a two-file bundle for every week.'],['banks','Practice sets',c.mcqs,'MCQs','Choose Weeks 1–6 or Weeks 7–14. Short rounds, full sets, and immediate explanations.'],['code','Code lab',c.guided,'guided exercises','Complete one missing line of Python, then compare it with a worked solution.'],['debugging','Debugging lab',c.debug,'repair exercises','Diagnose a faulty program, make a repair, and retain regression checks.'],['readings','Reading examples',c.reading,'reading programs','320 examples in the Wang collection and 80 Guttag-aligned companions, with code downloads.'],['programs/course','Course program studies',c.course,'course programs','Explore code, testing, objects, algorithms, and engineering calculations across Weeks 1–14.']];paint(`<div class="page-top"><span class="eyebrow">ENG 101 · PROGRAMMING FOR ENGINEERS</span><span class="date">Fall 2026 · 6 ECTS</span></div><section class="overview-hero"><span class="eyebrow">YOUR PRACTICE STUDIO</span><h1>Choose a focus.<br>Build your confidence.</h1><p>Read, predict, write, and debug your way through the course.</p><p class="muted">Instructor: Prof. Yanwei Wang</p><div class="actions"><a class="primary" href="#banks">Choose a practice set →</a><a class="secondary" href="#guide">Read the course guide</a></div></section><div class="stat-strip"><div class="stat"><div><strong>${s.done}<small> / ${c.total}</small></strong><span>Activities attempted</span></div></div><div class="stat"><div><strong>${s.done?Math.round(s.first/s.done*100)+'%':'—'}</strong><span>Correct on first try</span></div></div><div class="stat"><div><strong>${s.missed}</strong><span>Activities to revisit</span></div></div></div><section aria-labelledby="paths-heading"><div class="section-heading"><div><h2 id="paths-heading">How will you practise?</h2><p>Choose a collection or return to <a class="inline-link" href="#session">your session</a>.</p></div></div><div class="path-grid">${paths.map(([route,name,count,unit,desc])=>`<a class="panel path-card" href="#${route}"><span class="path-count">${count}<small>${unit}</small></span><h2>${name}</h2><p>${desc}</p><span class="path-link">Explore →</span></a>`).join('')}</div></section><section class="collection-banner"><div><h2>Practise by semester half</h2><p>${c.first} MCQs for Weeks 1–6 · ${c.second} MCQs for Weeks 7–14</p></div><div class="actions"><a class="secondary" href="#banks/weeks-1-6">Weeks 1–6 →</a><a class="secondary" href="#banks/weeks-7-14">Weeks 7–14 →</a></div></section>`,'home');}
function banks(){const c=collectionCounts();paint(`${practiceTabs('banks')}<div class="intro"><span class="eyebrow">PRACTICE SETS · THE FULL SEMESTER</span><h1>Choose your semester half.</h1><p>${c.mcqs} MCQs with explanations, organized into two collections. Choose a short practice round, work through a full set, or revisit missed questions in your session.</p></div><div class="bank-grid semester-grid"><section class="panel semester-card"><span class="tag">FOUNDATIONS · WEEKS 1–6</span><h2>Core Python and problem solving</h2><strong class="semester-count">${c.first} MCQs</strong><p>Variables and types, arithmetic and units, branches and loops, strings, functions, lists, recursion, and dictionaries.</p><p class="muted">${IMPORTED_MCQS.length} questions from Mock A–D plus 32 Studio originals and ${FOUNDATION_ADDITIONS.length} new questions. Browse by set or topic.</p><a class="primary" href="#banks/weeks-1-6">Open Weeks 1–6 →</a></section><section class="panel semester-card"><span class="tag">BUILDING FURTHER · WEEKS 7–14</span><h2>Objects, algorithms, and integration</h2><strong class="semester-count">${c.second} MCQs</strong><p>Testing and debugging, OOP and inheritance, efficiency, searching and sorting, language comparisons, and course review.</p><p class="muted">50 questions per week, with code traces and concepts. Browse by week, question type, or progress.</p><a class="primary" href="#banks/weeks-7-14">Open Weeks 7–14 →</a></section></div><section class="collection-banner"><div><h2>Looking for a different kind of practice?</h2><p>Write a line, repair a program, or explore a reading example.</p></div><div class="actions"><a class="secondary" href="#code">Code lab →</a><a class="secondary" href="#debugging">Debugging lab →</a><a class="secondary" href="#readings">Reading examples →</a></div></section>`,'banks');}
function quizReturn(){const page=run?.returnTo||'practice';const label=page==='banks/weeks-7-14'?'Weeks 7–14':page==='banks/weeks-1-6'?'Weeks 1–6':page.startsWith('topic/')?'Topic practice':page.startsWith('program/')?'Program study':page==='session'?'My session':'All topics';const section=page.startsWith('topic/')?'practice':page.startsWith('program/')?(PROGRAMS.find(p=>p.id===page.split('/')[1])?.reading?'readings':'programs'):page;return {page,label,section};}
